PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, code TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS remotes (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), site_id TEXT NOT NULL UNIQUE, location TEXT NOT NULL, address TEXT NOT NULL, city TEXT NOT NULL, province TEXT NOT NULL, jarkom TEXT NOT NULL CHECK(jarkom IN ('VSAT','M2M')), ip_lan TEXT NOT NULL, pic_name TEXT NOT NULL, pic_phone TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nprs (id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, remote_id INTEGER NOT NULL REFERENCES remotes(id), remote_status TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', pending_by TEXT NOT NULL DEFAULT 'Customer', started_at TEXT NOT NULL, online_at TEXT, closed_at TEXT, created_by TEXT NOT NULL, last_action TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_nprs_remote ON nprs(remote_id);
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY, npr_id INTEGER NOT NULL UNIQUE REFERENCES nprs(id), number TEXT NOT NULL UNIQUE, instruction TEXT NOT NULL CHECK(instruction IN ('Maintenance','Preventive Maintenance')), notes TEXT NOT NULL, created_at TEXT NOT NULL, report TEXT NOT NULL DEFAULT '', technician TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS actions (id INTEGER PRIMARY KEY AUTOINCREMENT, npr_id INTEGER NOT NULL REFERENCES nprs(id), kind TEXT NOT NULL, notes TEXT NOT NULL, remote_status TEXT NOT NULL, pending_by TEXT NOT NULL, occurred_at TEXT NOT NULL, created_by TEXT NOT NULL, attachment_name TEXT NOT NULL DEFAULT '', attachment_data TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_actions_npr ON actions(npr_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS gamas (id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, location TEXT NOT NULL, notes TEXT NOT NULL, started_at TEXT NOT NULL, online_at TEXT, closed_at TEXT, status TEXT NOT NULL DEFAULT 'OPEN', report TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gamas_sites (gamas_id INTEGER NOT NULL REFERENCES gamas(id), remote_id INTEGER NOT NULL REFERENCES remotes(id), PRIMARY KEY(gamas_id,remote_id));
CREATE TABLE IF NOT EXISTS gamas_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, gamas_id INTEGER NOT NULL REFERENCES gamas(id), notes TEXT NOT NULL, report TEXT NOT NULL DEFAULT '', occurred_at TEXT NOT NULL, created_by TEXT NOT NULL);
